const hits = $input.first().json.hits;

// Pick top 3 by points
const top3 = hits
  .sort((a, b) => b.points - a.points)
  .slice(0, 3);

const articlesHtml = top3
  .map((article, i) => {
    const url = article.url || `https://news.ycombinator.com/item?id=${article.objectID}`;
    const author = article.author || 'Unknown';
    const points = article.points || 0;
    const comments = article.num_comments || 0;
    return `
      <div style="margin-bottom: 24px; padding: 16px; border-left: 4px solid #0066cc; background: #f9f9f9;">
        <p style="margin: 0 0 8px; font-size: 11px; color: #888; text-transform: uppercase; letter-spacing: 1px;">Article ${i + 1}</p>
        <h2 style="margin: 0 0 8px; font-size: 18px;">
          <a href="${url}" style="color: #0066cc; text-decoration: none;">${article.title}</a>
        </h2>
        <p style="margin: 0; font-size: 13px; color: #555;">
          By <strong>${author}</strong> &nbsp;|&nbsp; ⬆️ ${points} points &nbsp;|&nbsp; 💬 ${comments} comments
        </p>
        <p style="margin: 8px 0 0;"><a href="${url}" style="font-size: 13px; color: #0066cc;">${url}</a></p>
      </div>`;
  })
  .join('');

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const emailHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333;">
  <h1 style="color: #0066cc; border-bottom: 2px solid #0066cc; padding-bottom: 12px;">
    🤖 Top AI Articles &mdash; ${today}
  </h1>
  <p style="color: #555;">Here are today's top 3 AI stories from Hacker News:</p>
  ${articlesHtml}
  <hr style="margin-top: 32px; border: none; border-top: 1px solid #ddd;">
  <p style="font-size: 12px; color: #999; text-align: center;">
    Powered by Hacker News &mdash; <a href="https://news.ycombinator.com" style="color: #999;">news.ycombinator.com</a>
  </p>
</body>
</html>`;

return [{ json: { emailHtml, articleCount: top3.length, date: today } }];
